"import os
import re
import json

CONV_ID = "a04a22a5-4ce7-494d-aae6-0302e7a97aa6"
TRANSCRIPT_PATH = rf"C:\Users\lorik\.gemini\antigravity\brain\{CONV_ID}\.system_generated\logs\transcript.jsonl"
OUTPUT_DIR = r"C:\Users\lorik\.gemini\antigravity\scratch\meow-8n\chats"
OUTPUT_PATH = os.path.join(OUTPUT_DIR, f"{CONV_ID}.jsonl")

# Patterns to scrub
EMAIL_PATTERN = re.compile(r"[\w\.-]+@[\w\.-]+\.\w+")
# Basic password/key patterns
PASS_PATTERN = re.compile(r"(PASS|password|passwd|key|IdentityFile)\s*[:=]\s*['\"]?[^\s'\"]+['\"]?", re.IGNORECASE)

def scrub(text):
    if not isinstance(text, str):
        return text
    text = EMAIL_PATTERN.sub("[REDACTED_EMAIL]", text)
    text = PASS_PATTERN.sub(r"\1=[REDACTED]", text)
    # Scrub SSH keys
    text = re.sub(r"ssh-ed25519 [A-Za-z0-9+/=]+", "ssh-ed25519 [REDACTED_KEY]", text)
    return text

def clean_object(obj):
    if isinstance(obj, dict):
        return {k: clean_object(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [clean_object(i) for i in obj]
    elif isinstance(obj, str):
        return scrub(obj)
    return obj

def main():
    if not os.path.exists(TRANSCRIPT_PATH):
        print(f"Transcript not found at {TRANSCRIPT_PATH}")
        return

    os.makedirs(OUTPUT_DIR, exist_ok=True)

    with open(TRANSCRIPT_PATH, "r", encoding="utf-8") as infile, \
         open(OUTPUT_PATH, "w", encoding="utf-8") as outfile:
        for line in infile:
            if not line.strip():
                continue
            try:
                data = json.loads(line)
                cleaned = clean_object(data)
                outfile.write(json.dumps(cleaned) + "\n")
            except Exception as e:
                print(f"Error parsing line: {e}")

    print(f"Cleaned transcript written to {OUTPUT_PATH}")

if __name__ == "__main__":
    main()
